import{_ as s,l as i,o as e,c as o,v as t,p as l,x as n,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"半衰期与开平阈值","description":"","frontmatter":{"title":"半衰期与开平阈值","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/half-life-bands.md","filePath":"quant/half-life-bands.md","lastUpdated":1789023840000}'),h={name:"quant/half-life-bands.md"};function m(c,a,u,A,B,k){const r=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="半衰期与开平阈值" tabindex="-1">半衰期与开平阈值 <a class="header-anchor" href="#半衰期与开平阈值" aria-label="Permalink to &quot;半衰期与开平阈值&quot;">​</a></h1><div class="epigraph"><p>距离法配对用历史标准差的两倍做开仓、回到均值做平仓；这是一条可复现的规则，不是从价差动力学推出来的最优障碍，半衰期与往返成本会改同一条规则该不该做。</p><footer>—— Gatev, Goetzmann and Rouwenhorst, Pairs Trading: Performance of a Relative-Value Arbitrage Rule, Review of Financial Studies 2006</footer></div><p><a href="/quant/ou-spread">OU 残差</a> 给出两个尺度：回复有多快（半衰期），偏离有多大（平稳标准差）。把它们变成订单，还缺开仓、平仓、止损与「抱太久就走」。Gatev、Goetzmann 与 Rouwenhorst 用形成期距离最小的配对，交易期在价差偏离历史两倍标准差时开仓、交叉时平仓，为相对价值提供了可对照的基准。Avellaneda–Lee 用 \\(s\\)-score 的 \\(\\pm 1.25\\) 一类阈值。最优障碍文献（如 Leung–Li）在 OU 加成本下解进出障碍，说明「两倍标准差」只是启发式。本篇写半衰期如何过滤配对、阈值如何被成本推动，以及样本内最优障碍为何在样本外失效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设价差 \\(z_t\\) 已标准化或已拟合 OU。规则要决定：在哪些 \\(z\\) 上开反向仓，在哪些 \\(z\\) 上平，是否用止损，是否用时间止损。没有成本时，OU 的最优策略倾向于「立刻上最大仓、在均值平」，因为期望拉力在偏离处最大。有买卖价差与冲击时，必须等偏离大到覆盖往返成本加风险补偿，否则 Sharpe 在摩擦后变负。</p><p>半衰期过滤是另一层：\\(\\kappa\\) 太小，资本占用长，结构断裂来得比回复早；\\(\\kappa\\) 太大，交易像噪声交易，成本占比高。Gatev 等人的距离配对没有显式 \\(\\kappa\\)，但形成期窗口与持有到交叉，隐含了「不要抱无限久」。问题是把这组启发式写成与 OU 参数、成本参数一致的约束，而不是再调一组魔术数字。</p><h3 id="两倍标准差从哪里来" tabindex="-1">两倍标准差从哪里来 <a class="header-anchor" href="#两倍标准差从哪里来" aria-label="Permalink to &quot;两倍标准差从哪里来&quot;">​</a></h3><p>Gatev–Goetzmann–Rouwenhorst 的 2σ 是形成期价差的样本标准差，不是 OU 平稳分布的 \\(\\sigma/\\sqrt{2\\kappa}\\)。形成期若含趋势，σ 被抬高，开仓变少；若过短，σ 被低估，开仓过密。2 没有最优性证明，好处是简单、可复现、少一个样本内优化维度。把 2 换成网格搜索的 1.5 或 2.5，必须把搜索本身纳入多重检验，否则夏普是过拟合。</p><p><span class="marginnote">「回到均值平仓」在无成本时合理，在有成本时往往不是最优：最优平仓障碍通常在均值的另一侧之前就该走，或甚至在均值同一侧的某个更近水平——因为再等交叉要付时间风险。启发式平仓在 0，是为了规则干净，不是因为 OU 的首达时间在 0 处最优。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>半衰期过滤。</strong> 由 AR(1) 的 \\(\\phi\\) 得 \\(t_{1/2}=\\ln 2/(-\\ln\\phi)\\)（时间单位与 \\(\\Delta\\) 一致）。设定上限：例如半衰期超过形成期的三分之一，则不做——还没回来，\\(\\beta\\) 或均值可能已经变了。设定下限：半衰期短于若干个交易间隔，且往返成本占平稳 \\(\\sigma\\) 的比例过高，则不做。过滤在形成期末做一次，避免用交易期信息选参数。</p><p><strong>固定倍数阈值。</strong> 开仓 \\(|z-\\mu|\\gt k s\\)，平仓 \\(|z-\\mu|\\lt k_{\\mathrm{exit}} s\\)，止损 \\(|z-\\mu|\\gt k_{\\mathrm{stop}} s\\)。\\(s\\) 用形成期或滚动窗口。时间止损：持有超过 \\(c\\cdot t_{1/2}\\) 仍未平则平，承认 OU 的首达时间有长尾。Gatev 规则近似 \\(k=2,\\ k_{\\mathrm{exit}}=0\\)，无显式止损。</p><p><strong>成本调整。</strong> 往返成本 \\(c\\)（价差单位）至少要求 \\(k s\\) 显著大于 \\(c\\)，否则开仓的期望收敛不够付摩擦。更细的做法是把 OU 的期望收益 \\(\\mathbb{E}[\\int \\kappa(\\mu-z)dt]\\) 在障碍间积分，减 \\(c\\)，再除以占用波动。Leung 与 Li 一类最优双障碍把这个问题写成控制，解出 \\(k\\) 随 \\(c,\\kappa,\\sigma\\) 变：成本升则 \\(|k|\\) 升。</p><h3 id="标准化-σ-还是分位数" tabindex="-1">标准化：σ 还是分位数 <a class="header-anchor" href="#标准化-σ-还是分位数" aria-label="Permalink to &quot;标准化：σ 还是分位数&quot;">​</a></h3><p>用标准差做 \\(k\\) 假定对称与近似高斯。残差若厚尾，2σ 开仓太频，应用经验分位数或 <a href="/quant/evt">EVT</a> 的超出阈值。\\(s\\)-score 用滚动均值与滚动波动，能适应异方差，但滚动窗口又是带宽：太短则阈值乱跳、假信号；太长则像全样本 OU。报告阈值时必须写 \\(s\\) 的定义窗口，否则规则不可复现。</p><p>Avellaneda–Lee 在因子残差上交易，阈值针对残差的 \\(s\\)-score，不是原始价格比。把他们的 1.25 套到 Engle–Granger 价差上，量纲已经不是同一套标准化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OU 下，从障碍 \\(a\\) 出发到 \\(b\\) 的期望时间有闭式，期望折现收益在无成本时对「更极端的 \\(a\\)」更大，但更极端意味着更少的交易次数。成本是每次进出的固定（或与波动成比例的）扣减，于是最优 \\(a\\) 是次数与每次期望利润的折中。半衰期进入折现：\\(\\kappa\\) 小，同样的障碍，期望等待长，折现后利润下降，障碍应更远或干脆不做。</p><p>时间止损的机制是截断首达时间的长尾，并在协整破裂时止损：若 \\(\\beta\\) 已经坏了，\\(z\\) 不会按 OU 回来，时间止损把「无限等待」关掉。它与价格止损不同：价格止损认 OU 仍成立但碰到更大的扩散实现；时间止损认模型可能已经错了。</p><p><span class="marginnote">形成期/交易期分离是 Gatev 等人控制前视的关键：配对与 σ 只用形成期。若每天重估 \\(k\\) 与名单却用含当天的滚动 σ，阈值会在大偏离当天被抬高，开仓被推迟，这是一种隐性的前视或至少是同步偏差，回测会好看。</span></p><h3 id="多重配对与拥挤" tabindex="-1">多重配对与拥挤 <a class="header-anchor" href="#多重配对与拥挤" aria-label="Permalink to &quot;多重配对与拥挤&quot;">​</a></h3><p>许多对同时用 2σ，信号在市场压力下相关：残差一起裂开，一起触发。组合层的开仓次数与杠杆不受单对规则约束。半衰期短的对往往是同一行业微观结构噪声，看起来夏普高，容量小。阈值应随参与率和冲击上调，否则单对回测的 \\(k=2\\) 在组合上变成不可执行的 \\(k\\)。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>最优障碍对 \\(\\kappa,\\sigma,c\\) 敏感，样本内校准的 \\(k\\) 在样本外 \\(\\kappa\\) 一变就错。更稳健的是粗网格加成本压力，而不是精细到 1.83σ。涨跌停、停牌让「交叉平仓」无法执行，规则必须定义替代平仓。分红与拆股会制造假突破，阈值应在复权序列上算，执行在实际可成交价上算。</p><p>不要用交易期最小化回撤去选 \\(k\\)。不要把止损设在刚好比回测里最大不利偏移远一点的地方。不要对半衰期三天的噪声对和半衰期三个月的协整对用同一 \\(k\\)——成本占比完全不同。</p><p>与 <a href="/quant/kalman-hedge">Kalman 对冲</a> 叠用时，\\(z\\) 每天被重定义，\\(\\sigma\\) 必须来自滤波创新而不是来自过时残差；否则阈值跟踪的是已经不交易的那条价差。Gatev 的距离法不估计 \\(\\beta\\) 的动态，阈值语义更简单，但对对冲比误设更敏感。</p><p><span class="marginnote">RFS 2006 的贡献是相对价值规则的可复现绩效与风险特征（包括回撤集中在某些时期），不是证明 2σ 最优。后续论文改阈值、改协整、改 Kalman，比较时应先对齐形成期长度与成本假设，再谈超额。</span></p>',27)),(e(),l(E,null,{default:n(()=>[d(r,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E4%BB%B7%E5%B7%AE%20z%20%2F%20s-score%22%5D%20--%3E%20HL%5B%22%E5%8D%8A%E8%A1%B0%E6%9C%9F%E8%BF%87%E6%BB%A4%22%5D%0A%20%20HL%20--%3E%20C%5B%22%E5%BE%80%E8%BF%94%E6%88%90%E6%9C%AC%20c%22%5D%0A%20%20C%20--%3E%20K%5B%22%E5%BC%80%E4%BB%93%E9%9A%9C%E7%A2%8D%20k(s%2Cc%2C%CE%BA)%22%5D%0A%20%20K%20--%3E%20E%5B%22%E5%B9%B3%E4%BB%93%3A%20%E5%9D%87%E5%80%BC%20%2F%20%E6%9B%B4%E8%BF%91%E9%9A%9C%E7%A2%8D%22%5D%0A%20%20K%20--%3E%20S%5B%22%E4%BB%B7%E6%A0%BC%E6%AD%A2%E6%8D%9F%22%5D%0A%20%20HL%20--%3E%20T%5B%22%E6%97%B6%E9%97%B4%E6%AD%A2%E6%8D%9F%20%E2%88%9D%20%E5%8D%8A%E8%A1%B0%E6%9C%9F%22%5D%0A%20%20E%20--%3E%20X%5B%22%E8%A7%84%E5%88%99%E5%8F%AF%E5%A4%8D%E7%8E%B0%3A%20%E5%86%99%E6%B8%85%E7%AA%97%E5%8F%A3%E4%B8%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20S%20--%3E%20X%0A%20%20T%20--%3E%20X%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半衰期过滤掉「回不来」与「回得太快以至于只剩成本」的配对；它是形成期约束，不是交易期调参。</li><li>2σ 开仓、回均值平仓是 Gatev 等人的可复现启发式；有成本时最优平仓一般不是均值交叉。</li><li>阈值的 \\(s\\) 必须定义窗口与是否滚动；厚尾时用分位数，异方差时用 \\(s\\)-score 一类局部尺度。</li><li>时间止损截断首达长尾并限制协整破裂后的无限等待。</li><li>样本内最优 \\(k\\) 极易过拟合；成本、冲击与拥挤会把单对阈值推远。</li><li>出处：Gatev, Goetzmann, Rouwenhorst, <em>Review of Financial Studies</em>, 2006；\\(s\\)-score 见 Avellaneda and Lee, <em>Quantitative Finance</em>, 2010；OU 加成本的最优障碍见 Leung and Li 等均值回复交易文献。</li></ul>',2))])}const b=s(h,[["render",m]]);export{f as __pageData,b as default};
